const TIERS: Record<number, AnswerRecord['tier']> = {
  10: 'BACKGROUND', 15: 'FAMILIAR', 30: 'UNCOMMON',
  60: 'RARE', 85: 'DEEP CUT', 100: 'SIGNAL FOUND'
};
function answer(aliases: string[], score: number, note: string): AnswerRecord {
  return { aliases, score, tier: TIERS[score], note };
}
